"""FM-16T original pathways: squared roots, ratios and polar geometry."""
import sympy as s
from calibration_bank import LEVELS,L
x,h,m=s.symbols('x h m',real=True); R=s.Rational; I=s.I; pi=s.pi
PATHS={'squared-roots':'ALG.related-quadratic.square','root-ratios':'ALG.related-quadratic.ratio','polar-geometry':'CPX.polar.interpret','modulus-constraints':'CPX.polar.modulus'}
RATIONALES={
'squared-roots':['Square signed numbers.','Diagnose squaring the sum instead of the roots.','Construct the squared-root quadratic.','Compose a shift and squaring using symmetric identities.','Reverse a squared-root transformation with a sign restriction.','Classify all real-root originals with a prescribed squared-root sum and product.'],
'root-ratios':['Compute reciprocal ratios.','Diagnose zero-root restrictions and repeated ratios.','Construct a ratio-root equation.','Recover the original product from the ratio-root sum.','Reconstruct a quadratic given a ratio and an unordered sign constraint.','Classify every ratio sum attainable by real roots with fixed nonzero sum.'],
'polar-geometry':['Identify distance and direction on the axes.','Distinguish modulus from directed argument.','Interpret equal moduli and opposite arguments.','Find midpoint and chord length from polar geometry.','Recover two equal-modulus points with prescribed midpoint.','Classify all ordered pairs on a circle with given real sum, including zero and tangent cases.'],
'modulus-constraints':['Compute a distance using Pythagoras.','Diagnose the absolute value of real and imaginary parts.','Compute exact moduli of Cartesian complex numbers.','Recover a coordinate from modulus and a half-plane constraint.','Solve simultaneous modulus equations exactly.','Classify intersections of two distance circles for every real radius parameter.']}
def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=2*v+4;d=2*v+5;S=a+b;P=a*b;F=x*x-S*x+P
 if path=='squared-roots':
  if l==1:
   f=[a*a,b*b];q=f'Square the two signed numbers {-a} and {b} separately.';ans=f'{f[0]}, {f[1]}';steps=[f'A negative number squared is positive: ({-a})^2={a*a}.',f'The other square is {b*b}.'];hint=['Multiply each number by itself.'];mist='Retaining a negative sign after squaring.'
  elif l==2:
   f=[S*S-2*P,P*P];q=f'A student says the sum of the squared roots of {L(F)}=0 is {S*S}. Correct the sum and product of the squared roots without finding the original roots.';ans=f'Sum {f[0]}, product {f[1]}.';steps=[f'Original sum {S}, product {P}.',f'Square the sum then subtract twice the product: {S*S}-2({P})={f[0]}.',f'The product of the squared roots is {P}^2={f[1]}.'];hint=['Expand the square of a sum.','Use the product rule.'];mist='Omitting the mixed term.'
  elif l==3:
   G=x*x-(S*S-2*P)*x+P*P;f=[G];q=f'Construct the monic equation with roots equal to the squares of the roots of {L(F)}=0, without solving the original equation.';ans=L(G)+'=0';steps=[f'Use original sum {S} and product {P}.',f'New sum {S*S-2*P}, new product {P*P}.',f'The monic equation is {L(G)}=0.'];hint=['Use symmetric expressions.','Apply the root-coefficient rule.'];mist='Squaring each coefficient.'
  elif l==4:
   T=S-2*d;Q=P-d*S+d*d;G=x*x-(T*T-2*Q)*x+Q*Q;f=[T,Q,G];q=f'The roots of {L(F)}=0 are each decreased by {d}, then squared. Construct the new monic equation using only sum and product identities.';ans=L(G)+'=0';steps=[f'After translation the sum is {T} and product {Q}.',f'After squaring the sum is {T*T-2*Q}, product {Q*Q}.',f'The resulting equation is {L(G)}=0.'];hint=['Translate before squaring.','Use the updated sum and product.'];mist='Shifting the squared roots instead.'
  elif l==5:
   G=x*x-(a*a+b*b)*x+a*a*b*b;H=x*x-(b-a)*x-a*b;f=[H];q=f'A real monic quadratic with two real roots has squared-root equation {L(G)}=0. The original roots have opposite signs and positive sum. Recover the original equation and prove uniqueness.';ans=L(H)+'=0';steps=[f'Factor the squared-root equation to obtain {a*a} and {b*b}.',f'The possible magnitudes are {a} and {b}; opposite signs and positive sum force {-a} and {b}.',f'The monic equation is {L(H)}=0; the other sign assignment has negative sum.'];hint=['Recover magnitudes first.','Use both sign conditions.'];mist='Choosing positive square roots only.'
  else:
   N=a*a+b*b;B=R(N*N,4);U=(N+s.sqrt(N*N-4*h))/2;V=(N-s.sqrt(N*N-4*h))/2;f=[N,B,U,V];q=f'For each real h, classify and construct every monic real quadratic with two real roots (counted with multiplicity) whose squares have sum {N} and product h. Count distinct original equations, not root orderings. Prove completeness at all boundaries.';ans=f'h<0 or h>{L(B)}: none; h=0: two; 0<h<{L(B)}: four; h={L(B)}: three. Put U={L(U)}, V={L(V)}. Form the monic equations from the unordered pairs (+/-sqrt(U), +/-sqrt(V)).';steps=[f'The squared roots U,V are nonnegative and satisfy U+V={N}, UV=h. Their quadratic has discriminant {N*N}-4h.',f'Nonnegative real U,V exist exactly for 0<=h<={L(B)}, since their sum is positive.',f'The unordered squared roots are U={L(U)}, V={L(V)}. Each original root has either sign of the corresponding square root.',f'At h=0 one magnitude is zero, so only two sign choices give distinct equations. For 0<h<{L(B)}, both magnitudes are positive and unequal, giving four distinct unordered signed pairs.',f'At h={L(B)} the magnitudes coincide: both positive, both negative, or one of each give three equations. For each signed pair r,t use (x-r)(x-t)=0. These exhaust all roots and reproduce the prescribed squares.'];hint=['First solve for the squared roots.','Count signs only after checking zero and equal magnitudes.'];mist='Always counting four distinct signed pairs, including at boundaries.'
 elif path=='root-ratios':
  if l==1:
   f=[R(a,b),R(b,a)];q=f'For the nonzero numbers {a} and {b}, calculate both ordered ratios in simplest form.';ans=', '.join(L(e) for e in f);steps=[f'Divide in each order to obtain {L(f[0])} and {L(f[1])}.'];hint=['Exchange numerator and denominator.'];mist='Using the same quotient twice.'
  elif l==2:
   f=[1,1];q=f'A student says the ratios of roots of (x-{a})^2=0 are distinct because there are two roots, and that the same ratio construction works for x(x-{b})=0. Explain both errors and give the two ratios in the first case.';ans='1, 1; the second construction is undefined.';steps=[f'Both roots in the first equation are {a}, so both ratios equal one.',f'The second equation has zero as a root, so one quotient would divide by zero. Both original roots must be nonzero.'];hint=['Check equal roots.','Check denominators.'];mist='Assuming two roots always give two distinct nonzero ratios.'
  elif l==3:
   T=R(S*S,P)-2;G=x*x-T*x+1;f=[G];q=f'Without solving {L(F)}=0, construct the monic equation whose roots are alpha/beta and beta/alpha, where alpha,beta are the original roots.';ans=L(G)+'=0';steps=[f'Sum of ratios is (alpha^2+beta^2)/(alpha beta)={L(T)}.',f'Product of ratios is one, since original product {P} is nonzero.',f'The equation is {L(G)}=0.'];hint=['Use a common denominator.','Use the symmetric sum of squares.'];mist='Using alpha+beta as the numerator.'
  elif l==4:
   T=R(S*S,P)-2;f=[P,F];q=f'A monic real quadratic has nonzero roots with sum {S}. Their two ratios have sum {L(T)}. Recover the original product and equation without finding the roots.';ans=f'Product {P}; {L(F)}=0.';steps=[f'Write ratio sum as {S*S}/P-2, where P is the unknown product.',f'Solve {S*S}/P={L(T+2)} to obtain P={P}.',f'The original equation is {L(F)}=0 and has nonzero roots.'];hint=['Use the ratio-sum identity backwards.'];mist='Forgetting the subtraction of two.'
  elif l==5:
   H=x*x-(a-b)*x-a*b;f=[H];q=f'A monic quadratic has two real roots whose ratios are {L(-R(a,b))} and {L(-R(b,a))}. The absolute product is {P} and the sum is negative. Recover the original equation and prove uniqueness.';ans=L(H)+'=0';steps=[f'Negative ratios force opposite signs, so product is {-P}.',f'Using the ratio-sum identity, the square of the sum is {(a-b)**2}.',f'The negative sum is {a-b}.',f'The unique equation is {L(H)}=0, whose roots {a} and {-b} satisfy both ratios.'];hint=['The product must be negative.','The sign of the sum removes ambiguity.'];mist='Retaining both signs of the sum.'
  else:
   D=d*d/(h+2);disc=s.factor(d*d-4*D);f=[D,disc,-2,2];q=f'For every real h, find all monic real quadratics with nonzero real roots of sum {d} such that alpha/beta+beta/alpha=h. Classify existence, construct the equation, and state when the ratio roots coincide.';ans=f'Exactly one equation for h<-2 or h>=2: {L(x*x-d*x+D)}=0. None otherwise. Ratio roots coincide only at h=2.';steps=[f'With nonzero product P, h={d*d}/P-2. Thus h=-2 is impossible and P={L(D)} otherwise.',f'The original discriminant is {L(disc)}. It is nonnegative exactly when h<-2 or h>=2; analyze the numerator and denominator signs separately.',f'For each admissible h the product is nonzero and the monic equation is {L(x*x-d*x+D)}=0, so it has the required real nonzero roots and the prescribed ratio sum.', 'The ratio roots have product one. They coincide only if h^2-4=0; h=-2 was excluded, so only h=2 remains. At that boundary the original roots are equal. The forced product proves uniqueness.'];hint=['Express h using the fixed sum and unknown product.','Do not multiply an inequality by an expression of unknown sign.'];mist='Including h=-2 or reversing an inequality incorrectly.'
 elif path=='polar-geometry':
  if l==1:
   f=[a,pi/2];q=f'A point lies {a} units vertically above the origin on an Argand diagram. Give its distance from the origin and its anticlockwise angle from the positive real axis in radians.';ans=f'{a}; {L(pi/2)}';steps=[f'The point is (0,{a}), so the distance is {a}.','The positive imaginary axis is a quarter turn anticlockwise: pi/2.'];hint=['Locate the imaginary axis.'];mist='Measuring the angle from the vertical axis.'
  elif l==2:
   f=[a,-pi/2];q=f'A student says the point -{a}i has modulus {-a} and argument pi/2. Correct both quantities using the geometric meaning of polar form.';ans=f'Modulus {a}; principal argument {L(-pi/2)}.';steps=[f'Distance is nonnegative: the point lies {a} units from the origin.', 'It lies on the negative imaginary axis, a clockwise quarter turn from the positive real axis.'];hint=['Distance cannot be negative.','Distinguish upward and downward directions.'];mist='Giving a signed distance.'
  elif l==3:
   T=[pi/6,pi/4,pi/3][v-1];z=a*(s.cos(T)+I*s.sin(T));w=s.conjugate(z);f=[z,w,2*T];q=f'Two points have modulus {a} and arguments {L(T)} and {L(-T)}. Give both Cartesian complex numbers and the smaller angle between their position vectors. Describe their symmetry.';ans=f'{L(z)}, {L(w)}; angle {L(2*T)}.';steps=[f'The coordinates are modulus times cosine and sine, giving {L(z)} and {L(w)}.',f'The points are reflected in the real axis. Their smaller angular separation is {L(2*T)}, below pi.'];hint=['Cosine is even and sine is odd.'];mist='Reflecting in the imaginary axis.'
  elif l==4:
   T=[pi/3,pi/4,pi/6][v-1];M=a*s.cos(T);D=2*a*s.sin(T);f=[M,D];q=f'Points P,Q have modulus {a} and arguments {L(T)} and {L(-T)}. Without expanding a modulus squared, find the midpoint and length of their chord using symmetry and right-triangle geometry.';ans=f'Midpoint {L(M)} on the real axis; length {L(D)}.';steps=[f'Symmetry places the midpoint on the real axis at {L(M)}.',f'Each half chord is perpendicular to the real axis and has length {L(a*s.sin(T))}.',f'The entire chord has length {L(D)}.'];hint=['Draw the two equal radii.','Use half the chord.'];mist='Using cosine for the perpendicular half chord.'
  elif l==5:
   r=s.sqrt(a*a+b*b);z=a+I*b;w=a-I*b;f=[z,w];q=f'Two distinct points on the Argand circle of radius {L(r)} centred at the origin have midpoint {a}. Find the two points and prove that no other unordered pair works.';ans=f'{L(z)}, {L(w)}.';steps=[f'The chord midpoint is nonzero and its radius is perpendicular to the chord. Thus the chord is vertical at real coordinate {a}.',f'Pythagoras gives imaginary coordinates +/-sqrt({a*a+b*b}-{a*a})=+/-{b}.',f'The two points are {L(z)} and {L(w)}. The vertical line has exactly these two intersections with the circle.'];hint=['The radius through a noncentral chord midpoint is perpendicular to the chord.'];mist='Allowing arbitrary chord directions through a noncentral midpoint.'
  else:
   U=h/2;V=s.sqrt(a*a-h*h/4);f=[-2*a,0,2*a,U,V];q=f'For every real h, classify all ordered pairs (z,w) of complex numbers with |z|=|w|={a} and z+w=h (real). Give the solution families and prove that the cases exhaust the circle geometry.';ans=f'|h|>{2*a}: none; h=+/-{2*a}: one pair z=w=h/2; 0<|h|<{2*a}: two ordered pairs z={L(U)} +/- i{L(V)}, w={L(U)} -/+ i{L(V)}; h=0: infinitely many, w=-z, |z|={a}.';steps=[f'The midpoint of the two points is h/2 on the real axis. Its distance from the origin cannot exceed radius {a}.',f'At |h|={2*a} the midpoint lies on the circle; both endpoints must equal it (otherwise the midpoint is strictly inside).', 'At h=0 every diameter works, so every z on the circle with w=-z is a solution.',f'For 0<|h|<{2*a} the chord is perpendicular to the nonzero midpoint radius, hence vertical. Pythagoras gives imaginary coordinate +/-{L(V)} and real coordinate h/2.', 'Both orderings are distinct and satisfy the original equations; no other chord direction is possible. This covers all h.'];hint=['Interpret the real sum as twice the midpoint.','Treat the centre separately from noncentral points.'];mist='Using the vertical-chord formula at the centre and missing infinitely many pairs.'
 else:
  if l==1:
   f=[s.sqrt(a*a+b*b)];q=f'Find the exact hypotenuse length of a right triangle with legs {a} and {b}.';ans=L(f[0]);steps=[f'Pythagoras gives sqrt({a*a}+{b*b})={L(f[0])}.'];hint=['Square both legs.'];mist='Adding the leg lengths.'
  elif l==2:
   f=[s.sqrt(a*a+b*b)];q=f'A student claims |{-a}+{b}i|={a+b} because modulus adds absolute component sizes. Correct the answer and explain using distance.';ans=L(f[0]);steps=[f'Modulus is Euclidean distance, so sqrt(({ -a})^2+{b}^2)={L(f[0])}.','Adding absolute coordinate values gives a different distance measure, not the complex modulus.'];hint=['Use Pythagoras, not component addition.'];mist='Adding absolute components.'
  elif l==3:
   Z=-a+b*I;W=b+(a+b)*I;f=[s.Abs(Z),s.Abs(W)];q=f'Calculate the exact moduli of {L(Z)} and {L(W)}. Simplify radicals where possible.';ans=', '.join(L(e) for e in f);steps=[f'First squared modulus is {a*a+b*b}, giving {L(f[0])}.',f'Second squared modulus is {b*b+(a+b)**2}, giving {L(f[1])}.'];hint=['Use the real and imaginary parts separately.'];mist='Forgetting the square root.'
  elif l==4:
   r=s.sqrt(a*a+b*b);z=-a-I*b;f=[z];q=f'Let z={-a}+yi with real y. Given |z|={L(r)} and Im(z)<0, find z and verify the modulus.';ans=L(z);steps=[f'Squaring the modulus gives {a*a}+y^2={a*a+b*b}.',f'Thus y=+/-{b}. The strict negative imaginary part forces y={-b}.',f'Substitution verifies |z|={L(r)}.'];hint=['Square the nonnegative modulus.','Use the half-plane condition.'];mist='Retaining the positive imaginary coordinate.'
  elif l==5:
   r=s.sqrt(a*a+b*b);c=d;w=s.sqrt((a-c)**2+b*b);f=[a+b*I,a-b*I];q=f'Find all z such that |z|={L(r)} and |z-{c}|={L(w)}. Prove no further solutions exist.';ans=', '.join(L(e) for e in f);steps=[f'Write z=u+iv. Squared distances give u^2+v^2={a*a+b*b} and (u-{c})^2+v^2={(a-c)**2+b*b}.',f'Subtracting forces u={a} since the centres are distinct.',f'Substitution gives v^2={b*b}, so v=+/-{b}. Both points verify the two nonnegative distances.'];hint=['Subtract the squared equations.','Check both signs.'];mist='Finding only one of the two intersections.'
  else:
   r=a;c=d;lo=c-r;hi=c+r;U=(r*r+c*c-h*h)/(2*c);V=s.sqrt(r*r-U*U);f=[lo,hi,U,V];q=f'For every real h classify the number of complex numbers satisfying |z|={r} and |z-{c}|=h. Find all such z in exact form, prove necessity and sufficiency, and account for negative h and tangency.';ans=f'None for h<{lo} or h>{hi}; one at h={lo} or h={hi}; two for {lo}<h<{hi}. Put u={L(U)}, v={L(V)}; z=u +/- iv in admissible cases.';steps=[f'A modulus is nonnegative, so negative h is impossible. With z=u+iv, the squared equations are u^2+v^2={r*r}, (u-{c})^2+v^2=h^2.',f'Subtraction gives u={L(U)}. Then v^2={r*r}-u^2, requiring -{r}<=u<={r}.',f'For h>=0, these inequalities are equivalent to {lo}<=h<={hi}. Outside this interval no points exist.',f'At either endpoint v=0, yielding one point. Inside the interval v=+/-{L(V)}, yielding two distinct points.', 'All constructed points satisfy both squared equations; since both prescribed moduli are nonnegative, they satisfy the original equations as well. The forced u and complete square-root choices prove exhaustiveness.'];hint=['Subtract the two squared distances.','Check the sign of h before taking square roots.'];mist='Accepting a negative radius after squaring or counting tangency twice.'
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hint,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[str(e) for e in f],likely_mistake=mist,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
